#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define BLOCK_ROWS 8
#define THREADS_X 32 // TILE_DIM
#define THREADS_Y 8 // TILE_DIM / 4

__global__ void matmul_kernel_vectorized_fixed(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_DIM][TILE_DIM];
    __shared__ float Bs[TILE_DIM][TILE_DIM];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE_DIM;
    int col = bx * TILE_DIM;

    float Cvals[4] = {0.0f};

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Each thread loads 4 elements of A and 4 elements of B
        for(int i=0; i<4; ++i) {
            int a_row = ty * 4 + i;
            int a_col = tx;
            int b_row = ty * 4 + i;
            int b_col = tx;
            if((row + a_row) < N && (t * TILE_DIM + a_col) < N)
                As[a_row][a_col] = A[(row + a_row) * N + t * TILE_DIM + a_col];
            else
                As[a_row][a_col] = 0.0f;

            if((t * TILE_DIM + b_row) < N && (col + b_col) < N)
                Bs[b_row][b_col] = B[(t * TILE_DIM + b_row) * N + col + b_col];
            else
                Bs[b_row][b_col] = 0.0f;
        }
        __syncthreads();

        for (int k = 0; k < TILE_DIM; ++k) {
            #pragma unroll
            for (int i = 0; i < 4; i++) {
                Cvals[i] += As[ty*4+i][k] * Bs[k][tx];
            }
        }
        __syncthreads();
    }

    for (int i = 0; i < 4; i++) {
        if ((row + ty*4 + i) < N && (col + tx) < N) {
            C[(row + ty*4 + i) * N + col + tx] = Cvals[i];
        }
    }
